/**
 * useApiKeys contract — mirrors useHgvTollReport.test.ts's pattern.
 * Do not edit this file to make it pass — edit useApiKeys.ts.
 *
 * Run (Windows, per WORKING_RULES "npm install/ci/build Windows'ta koşulur"):
 *   npm test -- useApiKeys --watchAll=false
 */
import { renderHook, waitFor, act } from "@testing-library/react";
import { useApiKeys, ApiKeyMeta } from "./useApiKeys";

let mockToken: string | null = "test-jwt";
jest.mock("store/useAuthStore", () => ({
  useAuthStore: (selector: (s: { token: string | null }) => unknown) => selector({ token: mockToken }),
}));

function mockFetchOnce(body: unknown, ok = true, status = 200) {
  (global.fetch as jest.Mock).mockResolvedValueOnce({
    ok,
    status,
    json: async () => body,
  });
}

const KEY_ROW: ApiKeyMeta = {
  id: "k1",
  key_prefix: "tfk_live_ab12cd3",
  label: "ERP integration",
  created_at: "2026-10-11T00:00:00Z",
  revoked_at: null,
  last_used_at: null,
};

beforeEach(() => {
  global.fetch = jest.fn();
  mockToken = "test-jwt";
});

afterEach(() => {
  jest.clearAllMocks();
});

test("on mount, lists the company's keys", async () => {
  mockFetchOnce({ api_keys: [KEY_ROW] });
  const { result } = renderHook(() => useApiKeys());
  await waitFor(() => expect(result.current.keys).toHaveLength(1));

  expect(result.current.keys).toEqual([KEY_ROW]);
  expect(result.current.loading).toBe(false);
  expect(result.current.error).toBeNull();

  const [url, init] = (global.fetch as jest.Mock).mock.calls[0];
  expect(String(url)).toMatch(/\/api\/subscription\/api-keys$/);
  expect((init as RequestInit).headers).toMatchObject({ Authorization: "Bearer test-jwt" });
});

test("no token -> no fetch, empty list", async () => {
  mockToken = null;
  const { result } = renderHook(() => useApiKeys());
  expect(global.fetch).not.toHaveBeenCalled();
  expect(result.current.keys).toEqual([]);
});

test("list failure surfaces as an error, not a thrown exception", async () => {
  mockFetchOnce({ error: "Internal Server Error" }, false, 500);
  const { result } = renderHook(() => useApiKeys());
  await waitFor(() => expect(result.current.error).not.toBeNull());
  expect(result.current.keys).toEqual([]);
});

test("createKey success stores the plaintext key once and refreshes the list", async () => {
  mockFetchOnce({ api_keys: [] }); // initial list on mount
  const { result } = renderHook(() => useApiKeys());
  await waitFor(() => expect(result.current.loading).toBe(false));

  mockFetchOnce({ api_key: { ...KEY_ROW, key: "tfk_live_plaintextvalue000000" } }, true, 201);
  mockFetchOnce({ api_keys: [KEY_ROW] }); // refresh after create

  await act(async () => {
    await result.current.createKey("ERP integration");
  });

  expect(result.current.newKey?.key).toBe("tfk_live_plaintextvalue000000");
  expect(result.current.keys).toEqual([KEY_ROW]);
  expect(result.current.createError).toBeNull();

  const [, createInit] = (global.fetch as jest.Mock).mock.calls[1];
  expect((createInit as RequestInit).method).toBe("POST");
  expect(JSON.parse((createInit as RequestInit).body as string)).toEqual({ label: "ERP integration" });
});

test("createKey failure sets createError, never throws, never sets newKey", async () => {
  mockFetchOnce({ api_keys: [] });
  const { result } = renderHook(() => useApiKeys());
  await waitFor(() => expect(result.current.loading).toBe(false));

  mockFetchOnce({ error: "Bad Request" }, false, 400);

  await act(async () => {
    await result.current.createKey();
  });

  expect(result.current.createError).toBe("create_failed");
  expect(result.current.newKey).toBeNull();
});

test("dismissNewKey clears the plaintext key from state", async () => {
  mockFetchOnce({ api_keys: [] });
  const { result } = renderHook(() => useApiKeys());
  await waitFor(() => expect(result.current.loading).toBe(false));

  mockFetchOnce({ api_key: { ...KEY_ROW, key: "tfk_live_x" } }, true, 201);
  mockFetchOnce({ api_keys: [KEY_ROW] });
  await act(async () => {
    await result.current.createKey();
  });
  expect(result.current.newKey).not.toBeNull();

  act(() => {
    result.current.dismissNewKey();
  });
  expect(result.current.newKey).toBeNull();
});

test("revokeKey success removes the key after refetching the list", async () => {
  mockFetchOnce({ api_keys: [KEY_ROW] });
  const { result } = renderHook(() => useApiKeys());
  await waitFor(() => expect(result.current.keys).toHaveLength(1));

  mockFetchOnce({ revoked: true });
  mockFetchOnce({ api_keys: [] }); // refresh after revoke

  await act(async () => {
    await result.current.revokeKey("k1");
  });

  expect(result.current.keys).toEqual([]);
  const [url, init] = (global.fetch as jest.Mock).mock.calls[1];
  expect(String(url)).toMatch(/\/api\/subscription\/api-keys\/k1$/);
  expect((init as RequestInit).method).toBe("DELETE");
});

test("revokeKey failure sets error, never throws", async () => {
  mockFetchOnce({ api_keys: [KEY_ROW] });
  const { result } = renderHook(() => useApiKeys());
  await waitFor(() => expect(result.current.keys).toHaveLength(1));

  mockFetchOnce({ error: "Not Found" }, false, 404);

  await act(async () => {
    await result.current.revokeKey("k1");
  });

  expect(result.current.error).toBe("revoke_failed");
});
